import re
from flows3 import *
ORA='#FF6B35'
def mini_prods(keys,c):
    cell=lambda k:f'<td width="50%" valign="top" style="width:50%;padding:5px;"><a href="{utm(P[k][3],c)}" style="display:block;text-decoration:none;background:{CARD};border:1px solid {BD};border-radius:14px;overflow:hidden;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="64" style="width:64px;line-height:0;"><img src="{U}sp-email/{P[k][2]}" width="64" height="64" style="display:block;border:0;"></td><td style="padding:8px 10px;text-align:left;font-family:{F};"><div style="font-size:13px;font-weight:800;color:#FFF;">{P[k][0]}</div><div style="font-size:11px;color:{MUT};">{P[k][1]}</div></td></tr></table></a></td>'
    return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>'+''.join(cell(k) for k in keys)+'</tr></table>'
def nohelp(f): return re.sub(r'<div style="font-size:15px;font-weight:700;color:#FFFFFF;margin-bottom:12px;">Fragen\?.*?</table><div style="height:28px;"></div>','',f,flags=re.S)

# --- Code-Erinnerung: Countdown ---
ER=body(bar('Erinnerung')
 +row(f'<table role="presentation" align="center" cellpadding="0" cellspacing="0"><tr><td style="{CHR if False else ""}"></td></tr></table>'
   +f'<div style="display:inline-block;background-color:#3A4048;background-image:linear-gradient(135deg,#F2F4F6 0%,#8E959E 35%,#3A4048 60%,#C9CED6 100%);border-radius:26px;padding:2px;"><div style="background:{CARD};border-radius:24px;padding:22px 34px;"><div style="font-size:84px;line-height:1;font-weight:800;color:#FFF;">5</div><div style="font-size:12px;font-weight:700;letter-spacing:.24em;color:{MUT};margin-top:6px;">TAGE ÜBRIG</div></div></div>'
   +f'<div style="font-size:30px;line-height:1.12;font-weight:800;color:#FFF;margin:24px 0 10px;">Dein Code<br>läuft bald ab.</div><div style="font-size:15px;line-height:1.55;color:{MUT};">Du hast ihn noch nicht eingelöst – danach verfällt er.</div>','34px 20px 24px')
 +row(f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:separate;border:1px solid {BD};border-radius:16px;overflow:hidden;"><tr><td width="32%" style="background:#FFFFFF;padding:16px 4px;text-align:center;font-family:{F};"><div style="font-size:26px;font-weight:800;color:#0D0F12;line-height:1;">10 %</div></td><td style="background:{CARD};padding:14px 10px;text-align:center;border-left:2px dashed {IN};font-family:{F};"><div style="font-size:20px;font-weight:800;font-family:{MONO};color:#FFF;letter-spacing:.03em;">HALLO-7KQ2M</div><div style="font-size:11px;color:{DIM};margin-top:3px;">gültig bis 14.11.2026</div></td></tr></table><div style="height:16px;"></div>'+btn('Code jetzt einlösen','#'),'0 20px 28px')
 +row(f'<div style="text-align:left;font-size:12px;font-weight:700;letter-spacing:.16em;color:{DIM};margin-bottom:8px;">AM MEISTEN GEKAUFT</div>'+mini_prods(['reta','ghk'],'x'),'0 15px 30px')+nohelp(foot()))

# --- Nachkauf: Produkte zuerst ---
big=''.join(f'<td width="50%" valign="top" style="width:50%;padding:5px;"><div style="background:{CARD};border:1px solid {BD};border-radius:16px;overflow:hidden;text-align:left;"><img src="{i[0]}" width="150" style="display:block;width:100%;height:auto;border:0;"><div style="padding:12px;font-family:{F};"><div style="font-size:15px;font-weight:800;color:#FFF;">{i[1]}</div><div style="font-size:12px;color:{MUT};margin-top:2px;">{i[2]}</div></div></div></td>' for i in CART)
NK=body(bar('Nachbestellen')
 +row(f'<div style="text-align:left;"><div style="font-size:12px;font-weight:700;letter-spacing:.16em;color:{DIM};">VOR 4 WOCHEN BESTELLT</div><div style="font-size:34px;line-height:1.08;font-weight:800;color:#FFF;letter-spacing:-.02em;margin:8px 0 18px;">Zeit für<br>Nachschub?</div></div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 -5px;width:calc(100% + 10px);"><tr>{big}</tr></table><div style="height:16px;"></div>'+btn('Alles mit einem Klick nachbestellen','#')+f'<div style="font-size:12px;color:{DIM};margin-top:10px;">Landet direkt im Warenkorb – du kannst vor dem Bestellen noch alles ändern.</div>','30px 20px 28px')
 +abo('x')+nohelp(foot()))

# --- Nachkauf 2: kurze persönliche Notiz ---
thumbs2=''.join(f'<td width="56" style="width:56px;padding-right:8px;"><img src="{i[0]}" width="48" height="48" style="display:block;border-radius:10px;border:0;"></td>' for i in CART)
N2=body(bar('Kurzer Hinweis')
 +row(f'<div style="text-align:left;border-left:3px solid #8E959E;padding:4px 0 4px 16px;font-family:{F};"><div style="font-size:24px;font-weight:800;color:#FFF;margin-bottom:12px;">Noch alles da?</div><div style="font-size:16px;line-height:1.65;color:#C9CDD2;">Hallo,<br><br>nur eine kurze Nachricht: Falls dein Vorrat langsam knapp wird – deine letzte Bestellung liegt mit einem Klick wieder im Warenkorb.<br><br>Und falls du Fragen hast, antworte einfach auf diese Mail.<br><br><span style="color:#FFF;font-weight:700;">Dein Peptrium-Team</span></div></div>','36px 24px 24px')
 +row(f'<table role="presentation" cellpadding="0" cellspacing="0"><tr>{thumbs2}</tr></table><div style="height:16px;"></div>'+btn('Nachbestellen','#'),'0 24px 32px','#12151A').replace('text-align:center','text-align:left',1)+nohelp(foot()))

# --- Rückgewinnung: Vollbild + Comeback-Ticket ---
RG=body(f'<tr><td style="padding:0;line-height:0;background:{BG};"><img src="{U}sp-email/nl-hero-pen.jpg" width="600" style="display:block;width:100%;height:auto;border:0;"></td></tr>'
 +row(f'<div style="font-size:12px;font-weight:700;letter-spacing:.2em;color:{MUT};">LANGE NICHT GESEHEN</div><div style="font-size:36px;line-height:1.05;font-weight:800;color:#FFF;margin:10px 0 12px;letter-spacing:-.02em;">Wir vermissen<br>dich.</div><div style="font-size:15px;line-height:1.55;color:{MUT};">Als kleines Dankeschön für dein Comeback:</div>','24px 20px 20px')
 +row(f'<div style="background-color:#3A4048;background-image:linear-gradient(135deg,#F2F4F6 0%,#8E959E 35%,#3A4048 60%,#C9CED6 100%);border-radius:20px;padding:2px;"><div style="background:#0B0D10;border-radius:18px;padding:26px 16px;"><div style="font-size:12px;font-weight:700;letter-spacing:.2em;color:{MUT};">DEIN COMEBACK-CODE</div><div style="font-size:60px;font-weight:800;color:#FFF;line-height:1.1;margin:6px 0;">10 %</div><div style="font-size:22px;font-weight:800;font-family:{MONO};color:#D9DDE2;letter-spacing:.04em;">COMEBACK-4XQ9P</div><div style="font-size:12px;color:{DIM};margin-top:8px;">nur 14 Tage gültig · bis 01.12.2026</div></div></div><div style="height:16px;"></div>'+btn('Jetzt einlösen','#'),'0 20px 30px')
 +row(f'<div style="text-align:left;"><div style="font-size:12px;font-weight:700;letter-spacing:.16em;color:{DIM};margin-bottom:6px;">GERADE BELIEBT</div><div style="font-size:20px;font-weight:800;color:#FFF;margin-bottom:12px;">Fertig gemischt oder klassisch</div></div>'+mini_prods(['pen','reta'],'x'),'0 15px 30px')+nohelp(foot()))
for k,v in {'v_erinnerung':ER,'v_nachkauf':NK,'v_nachkauf2':N2,'v_rueckgewinnung':RG}.items(): open(k+'.html','w').write(f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:{BG};">{v}</body></html>')
